 if(opts.id!=null)nextId=Math.max(nextId,opts.id+1);g.position.copy(position||new THREE.Vector3((parts.length%4-1.5)*1.7,.65,Math.floor(parts.length/4)*1.55));scene.add(g);g.updateMatrixWorld(true);const bb=new THREE.Box3().setFromObject(g),sz=bb.getSize(new THREE.Vector3());g.userData.baseSize.set(Math.max(.05,sz.x),Math.max(.05,sz.y),Math.max(.05,sz.z));parts.push(g);if(!opts.silent){select(g);say(g.userData.name+' drawn and added to bench');}return g;
